insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('f6752e56-b73d-58e7-bbca-396f10f5a935', 'rg4-context-clues-p01', (select id from public.skills where slug = 'read-g4-context-clues'), null,
        '3-5', $q$Floating Otters$q$, $q$Sea otters spend almost their whole lives in the cold ocean. Unlike most sea animals, they have no thick layer of fat to keep them warm. Instead, they have very dense fur. It is packed so tightly that a patch the size of a postage stamp holds more hairs than a person has on a whole head.

To keep that fur working, otters must groom it many times a day. They comb it with their paws, rub it clean, and blow air into it. The trapped air keeps cold water away from their skin. It also makes them buoyant, so they float easily on their backs like little rafts.

Sea otters are clever eaters, too. An otter dives to the sea floor and grabs a clam. Then it floats on its back, sets a flat rock on its belly, and bangs the shell against the rock until it cracks.

Otters are vital to the kelp forests where they live. Kelp is a tall seaweed, and sea urchins love to eat it. Without otters to eat them, urchins would become abundant, and soon there would be thousands of them. They would chew the kelp forest down to bare rock. So by eating urchins, otters protect the whole forest and the fish that live in it.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
